// Min Stack Design with O(1) minimum lookup
struct MinStack {
    private var stack = AnimatedStack<Int>()
    private var minStack = AnimatedStack<Int>()

    mutating func push(_ val: Int) {
        stack.push(val)
        if minStack.isEmpty || val <= (minStack.peek() ?? val) {
            minStack.push(val)
        }
    }

    mutating func pop() {
        if let popped = stack.pop() {
            if popped == minStack.peek() {
                minStack.pop()
            }
        }
    }

    func top() -> Int {
        return stack.peek() ?? -1
    }

    func getMin() -> Int {
        return minStack.peek() ?? -1
    }
}

